import re
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

# Whitelist of allowed characters for safe evaluation
# Digits, operators, parentheses, and whitespace only
SAFE_CHAR_PATTERN = re.compile(r'^[0-9+\-*/().\s]+$')


def safe_eval(expression):
    """
    Safely evaluate a simple arithmetic expression.
    Only supports integers/floats and +, -, *, / operators.
    """
    if not isinstance(expression, str):
        raise ValueError("Expression must be a string")

    # Strip whitespace to check core characters, but keep original for eval
    expr = expression.strip()

    # Validate characters
    if not SAFE_CHAR_PATTERN.match(expr):
        raise ValueError("Expression contains invalid characters")

    # Prevent multiple dots in one number (basic check)
    # Split by operators to check individual numbers
    # This is a simple heuristic to catch things like "1.2.3"
    parts = re.split(r'([+\-*/])', expr)
    for part in parts:
        part = part.strip()
        if part and '.' in part:
            # Count dots in this segment
            if part.count('.') > 1:
                raise ValueError("Invalid number format")

    # Use eval with no builtins for safety
    # Since we validated characters, the risk is minimal for basic arithmetic
    try:
        result = eval(expr, {"__builtins__": None}, {})
        # Ensure result is a number, not something weird
        if isinstance(result, (int, float)):
            return str(result)
        else:
            raise ValueError("Expression did not evaluate to a number")
    except ZeroDivisionError:
        raise ValueError("Division by zero")
    except Exception as e:
        raise ValueError(f"Calculation error: {str(e)}")


@app.route('/calculator', methods=['POST'])
def calculator():
    data = request.get_json(silent=True)
    if not data or 'expression' not in data:
        return jsonify({"error": "Invalid input"}), 400

    expression = data.get('expression')

    if not isinstance(expression, str) or not expression.strip():
        return jsonify({"error": "Invalid input"}), 400

    try:
        result = safe_eval(expression)
        return jsonify({"result": result}), 200
    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    except Exception as e:
        return jsonify({"error": "Internal server error"}), 500


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
